// ===== Bootstrap global: tema Shoelace dentro de TODOS os <lexml-ui-*> =====
const SHOELACE_THEME_URL =
  'https://early.webawesome.com/webawesome@3.0.0-beta.4/dist/styles/themes/shoelace.css';

const isLexmlHost = (el: Element) =>
  el.tagName.startsWith('LEXML-UI-') || el.tagName === 'AUTOCOMPLETE-UI-ASYNC';

function injectThemeStyle(root: ShadowRoot) {
  if (!root.querySelector('style[data-wa-shoelace]')) {
    const style = document.createElement('style');
    style.setAttribute('data-wa-shoelace', '');
    style.textContent = `@import url('${SHOELACE_THEME_URL}');`;
    root.prepend(style); // no topo, melhor precedência
  }
}

function ensureThemeScope(root: ShadowRoot) {
  // se já existe wrapper, ok
  if (root.querySelector('[data-wa-theme-scope]')) return;

  // pegue tudo que já está no root (menos o <style data-wa-shoelace>)
  const keep = new Set<Node>(root.querySelectorAll('style[data-wa-shoelace]'));
  const toMove: Node[] = [];
  root.childNodes.forEach(n => {
    if (!keep.has(n)) toMove.push(n);
  });

  // se ainda não renderizou nada, deixa o observer cuidar depois
  if (toMove.length === 0) return;

  // cria o wrapper com as classes do tema (escopo exigido pela folha Shoelace)
  const scope = document.createElement('div');
  scope.setAttribute('data-wa-theme-scope', '');
  scope.classList.add(
    'wa-theme-shoelace',
    'wa-palette-shoelace',
    'wa-brand-blue',
  );

  root.appendChild(scope);
  toMove.forEach(n => scope.appendChild(n));
}

function themeShadowRoot(root: ShadowRoot) {
  injectThemeStyle(root);
  ensureThemeScope(root);

  // observa futuras inserções no root para manter o wrapper correto
  if (!(root as any).__waThemeObserved) {
    (root as any).__waThemeObserved = true;
    const mo = new MutationObserver(() => ensureThemeScope(root));
    mo.observe(root, { childList: true });
  }
}

function installShoelaceThemeForLexml() {
  // 1) intercepta attachShadow para pegar roots assim que nascerem
  const origAttach = (Element.prototype as any).attachShadow;
  if (!(window as any).__waThemePatched) {
    (Element.prototype as any).attachShadow = function (
      init: ShadowRootInit,
    ): ShadowRoot {
      const root: ShadowRoot = origAttach.call(this, init);
      if (isLexmlHost(this as Element)) themeShadowRoot(root);
      return root;
    };
    (window as any).__waThemePatched = true;
  }

  // 2) aplica de imediato em hosts já montados
  document.querySelectorAll('*').forEach(el => {
    if (isLexmlHost(el)) {
      const root = (el as any).shadowRoot as ShadowRoot | null;
      if (root) themeShadowRoot(root);
    }
  });

  // 3) observa a árvore por futuros hosts (caso o shadow já exista ao conectar)
  const docMO = new MutationObserver(records => {
    for (const r of records) {
      r.addedNodes.forEach(n => {
        if (n instanceof HTMLElement && isLexmlHost(n)) {
          const root = (n as any).shadowRoot as ShadowRoot | null;
          if (root) themeShadowRoot(root);
        }
      });
    }
  });
  docMO.observe(document.documentElement, { childList: true, subtree: true });
}

// dispara o bootstrap
installShoelaceThemeForLexml();
